        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: var(--font-main);
            line-height: 1.4;
            -webkit-font-smoothing: antialiased;
            overflow-x: hidden;
        }

        /* Utilities */
        .container {
            max-width: 1440px;
            margin: 0 auto;
            padding: 0 20px;
        }

        .flex { display: flex; }
        .grid { display: grid; }
        .uppercase { text-transform: uppercase; }
        .mono { font-family: var(--font-mono); }
        .bold { font-weight: 700; }
        .red-text { color: var(--accent-color); }

        a { color: inherit; text-decoration: none; cursor: pointer; }
        ul { list-style: none; }

        /* HEADER */
        header {
            background: #000;
            color: #fff;
            font-size: 11px;
            letter-spacing: 0.5px;
            padding: 12px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 2px solid #000;
        }

        header .brand { font-weight: 900; letter-spacing: 1px; }
        header .stats span { margin-left: 15px; opacity: 0.8; }
        header .live-badge { 
            border: 1px solid #fff; 
            padding: 2px 6px; 
            margin-left: 10px; 
            font-weight: bold;
        }

        /* MAIN LAYOUT */
        main {
            display: grid;
            grid-template-columns: 2fr 1fr;
            min-height: 100vh;
            border-right: 1px solid #000;
            border-bottom: 1px solid #000;
        }

        @media (max-width: 900px) {
            main { grid-template-columns: 1fr; }
            aside { display: none; } /* Hide sidebar on mobile for simplicity or stack it */
        }

        /* LEFT COLUMN (HERO) */
        .hero-section {
            padding: 60px 40px;
            border-right: 1px solid #000;
        }

        .breadcrumbs {
            font-family: var(--font-mono);
            font-size: 10px;
            margin-bottom: 30px;
            color: #666;
            letter-spacing: 1px;
        }

