            border: 2px solid #000;
            padding: 15px 25px;
            font-size: 12px;
            font-weight: 800;
            text-transform: uppercase;
            cursor: pointer;
            transition: all 0.1s;
            display: inline-flex;
            align-items: center;
        }

        .brutal-btn:hover {
            background: #000;
            color: #fff;
            box-shadow: 4px 4px 0 var(--accent-color);
        }

        .brutal-btn::after {
            content: '→';
            margin-left: 10px;
            font-size: 10px;
        }

        .disclaimer {
            font-size: 10px;
            color: #888;
            max-width: 500px;
            line-height: 1.5;
            font-family: var(--font-mono);
            text-transform: uppercase;
