            grid-column: 1 / -1;
            border-top: 1px solid #000;
            padding: 80px 40px;
            background: #fff;
        }

        .section-meta {
            font-family: var(--font-mono);
            font-size: 10px;
            color: #888;
            margin-bottom: 20px;
            text-transform: uppercase;
