            gap: 1px;
            background: #eee; /* Gap color */
            border: 1px solid #eee;
        }

        .q-item {
            background: #fff;
            padding: 40px;
            display: grid;
            grid-template-columns: 60px 1fr auto;
            gap: 30px;
            align-items: start;
        }

