        .q-content h3 {
            font-size: 20px;
            font-weight: 800;
            text-transform: uppercase;
            margin-bottom: 15px;
            line-height: 1.2;
        }

        .q-content p {
            font-size: 14px;
            color: #555;
            line-height: 1.6;
        }

        .q-action {
            font-size: 10px;
            font-weight: 800;
            color: var(--accent-color);
            text-transform: uppercase;
